using sv_89c6c25afaa34429b2e7936298b9b0bc.Services;

namespace sv_89c6c25afaa34429b2e7936298b9b0bc.Components.Pages;

public partial class Settings
{
    private string activeSection = "Profile";
    private bool isSaving;
    private string? toastMessage;
    private string toastType = "toast-success";

    // Profile
    private UserProfile? profile;
    private EditableProfile editProfile = new();

    // Notifications
    private NotificationPrefs? notificationPrefs;
    private EditableNotifications editNotifications = new();
    private readonly List<string> allChannels = new() { "general", "announcements", "updates", "marketing", "engineering", "support" };

    // Security
    private SecuritySettings? securitySettings;
    private bool changePasswordExpanded;
    private string currentPassword = string.Empty;
    private string newPassword = string.Empty;
    private string confirmPassword = string.Empty;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private AppearanceSettings? appearanceSettings;
    private EditableAppearance editAppearance = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadSection(activeSection);
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        DismissToast();
        await LoadSection(section);
    }

    private async Task LoadSection(string section)
    {
        switch (section)
        {
            case "Profile":
                if (profile is null)
                {
                    profile = await SettingsService.GetProfileAsync();
                    editProfile = EditableProfile.FromProfile(profile);
                }
                break;
            case "Notifications":
                if (notificationPrefs is null)
                {
                    notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                    editNotifications = EditableNotifications.FromPrefs(notificationPrefs);
                }
                break;
            case "Security":
                if (securitySettings is null)
                {
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                }
                break;
            case "Appearance":
                if (appearanceSettings is null)
                {
                    appearanceSettings = await SettingsService.GetAppearanceAsync();
                    editAppearance = EditableAppearance.FromSettings(appearanceSettings);
                }
                break;
        }
    }

    // Profile methods
    private async Task SaveProfile()
    {
        isSaving = true;
        try
        {
            var updated = new UserProfile(editProfile.DisplayName, editProfile.Email, editProfile.AvatarUrl, editProfile.Bio);
            await SettingsService.SaveProfileAsync(updated);
            profile = updated;
            ShowToast("Profile saved successfully!", "toast-success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error saving profile: {ex.Message}", "toast-error");
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardProfileChanges()
    {
        if (profile is not null)
        {
            editProfile = EditableProfile.FromProfile(profile);
        }
    }

    // Notification methods
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !editNotifications.MutedChannels.Contains(channel))
        {
            editNotifications.MutedChannels.Add(channel);
        }
        else if (!isMuted)
        {
            editNotifications.MutedChannels.Remove(channel);
        }
    }

    private async Task SaveNotifications()
    {
        isSaving = true;
        try
        {
            var updated = new NotificationPrefs(
                editNotifications.EmailNotifications,
                editNotifications.PushNotifications,
                editNotifications.WeeklyDigest,
                new List<string>(editNotifications.MutedChannels));
            await SettingsService.SaveNotificationPrefsAsync(updated);
            notificationPrefs = updated;
            ShowToast("Notification preferences saved!", "toast-success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error saving preferences: {ex.Message}", "toast-error");
        }
        finally
        {
            isSaving = false;
        }
    }

    // Security methods
    private async Task ChangePassword()
    {
        if (newPassword != confirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "toast-error");
            return;
        }

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "toast-error");
            return;
        }

        isSaving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = string.Empty;
            newPassword = string.Empty;
            confirmPassword = string.Empty;
            changePasswordExpanded = false;
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Password updated successfully!", "toast-success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error changing password: {ex.Message}", "toast-error");
        }
        finally
        {
            isSaving = false;
        }
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is null) return;

        try
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked successfully.", "toast-success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error revoking session: {ex.Message}", "toast-error");
        }
        finally
        {
            sessionToRevoke = null;
        }
    }

    // Appearance methods
    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{editAppearance.Theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{editAppearance.FontSize.ToLowerInvariant()}");
        if (editAppearance.CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        isSaving = true;
        try
        {
            var updated = new AppearanceSettings(editAppearance.Theme, editAppearance.FontSize, editAppearance.Language, editAppearance.CompactMode);
            await SettingsService.SaveAppearanceAsync(updated);
            appearanceSettings = updated;
            ShowToast("Appearance settings saved!", "toast-success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error saving appearance: {ex.Message}", "toast-error");
        }
        finally
        {
